files.content:
:root {
  --bg: #2d1b2e;
  --card-bg: #3e2a3f;
  --text: #f0e6d2;
  --accent: #f4a261;
  --accent-hover: #e76f51;
  --border: #6b4c6b;
  --error: #e63946;
  --success: #2a9d8f;
  --pixel-size: 4px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  line-height: 1.5;
  color: var(--text);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  background-image: linear-gradient(45deg, var(--bg) 25%, transparent 25%),
                    linear-gradient(-45deg, var(--bg) 25%, transparent 25%),
                    linear-gradient(45deg, transparent 75%, var(--bg) 75%),
                    linear-gradient(-45deg, transparent 75%, var(--bg) 75%);
  background-size: 16px 16px;
  background-position: 0 0, 0 8px, 8px -8px, -8px 0px;
}

.card {
  background: var(--card-bg);
  border: var(--pixel-size) solid var(--border);
  border-radius: 0;
  padding: 24px;
  max-width: 600px;
  width: 100%;
  box-shadow: 8px 8px 0 rgba(0,0,0,0.3);
}

.pixel-header {
  text-align: center;
  margin-bottom: 24px;
}

h1 {
  font-size: 1.75rem;
  font-weight: 700;
  letter-spacing: 1px;
  text-transform: uppercase;
  color: var(--accent);
  text-shadow: 2px 2px 0 var(--bg);
  margin-bottom: 8px;
}

.subtitle {
  font-size: 0.9rem;
  opacity: 0.8;
}

h2 {
  font-size: 1.25rem;
  margin: 20px 0 12px;
  padding-bottom: 4px;
  border-bottom: 2px dashed var(--border);
  color: var(--accent);
}

.form-group {
  margin-bottom: 16px;
}

label {
  display: block;
  margin-bottom: 4px;
  font-weight: 600;
  font-size: 0.95rem;
}

select, input[type="number"], input[type="text"] {
  width: 100%;
  padding: 10px 12px;
  font-size: 1rem;
  font-family: inherit;
  color: var(--text);
  background: var(--bg);
  border: 3px solid var(--border);
  border-radius: 0;
  outline: none;
  transition: border-color 0.1s, box-shadow 0.1s;
}

select:focus, input:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(244, 162, 97, 0.3);
}

.pixel-btn {
  display: inline-block;
  padding: 12px 24px;
  font-size: 1rem;
  font-weight: 700;
  font-family: inherit;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--bg);
  background: var(--accent);
  border: 3px solid var(--border);
  border-radius: 0;
  cursor: pointer;
  box-shadow: 4px 4px 0 var(--border);
  transition: transform 0.05s, box-shadow 0.05s, background 0.1s;
}

.pixel-btn:hover {
  background: var(--accent-hover);
  box-shadow: 4px 4px 0 var(--bg);
}

.pixel-btn:active {
  transform: translate(4px, 4px);
  box-shadow: 0 0 0 var(--border);
}

.pixel-btn:focus-visible {
  outline: 3px solid var(--text);
  outline-offset: 2px;
}

.error {
  color: var(--error);
  font-size: 0.9rem;
  min-height: 1.2em;
  margin-bottom: 8px;
  font-weight: 600;
}

.expense-list {
  list-style: none;
  margin: 0;
  padding: 0;
}

.expense-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 8px 0;
  border-bottom: 1px solid var(--border);
  gap: 8px;
  flex-wrap: wrap;
}

.expense-item:last-child {
  border-bottom: none;
}

.expense-info {
  flex: 1;
  min-width: 0;
  word-break: break-word;
}

.expense-amount {
  font-weight: 700;
  color: var(--accent);
  white-space: nowrap;
}

.remove-btn {
  background: transparent;
  border: 2px solid var(--error);
  color: var(--error);
  font-size: 0.8rem;
  padding: 4px 8px;
  cursor: pointer;
  font-family: inherit;
  font-weight: 600;
  border-radius: 0;
  transition: background 0.1s, color 0.1s;
}

.remove-btn:hover {
  background: var(--error);
  color: var(--bg);
}

.remove-btn:focus-visible {
  outline: 3px solid var(--text);
  outline-offset: 2px;
}

.totals-grid, .balances-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(120px, 1fr));
  gap: 12px;
  margin-bottom: 16px;
}

.total-card, .balance-card {
  background: var(--bg);
  border: 3px solid var(--border);
  padding: 12px;
  text-align: center;
}

.total-card .name, .balance-card .name {
  font-weight: 700;
  margin-bottom: 4px;
}

.total-card .amount {
  font-size: 1.2rem;
  color: var(--accent);
  font-weight: 700;
}

.balance-card .status {
  font-size: 1rem;
  font-weight: 700;
}

.balance-card .status.owes {
  color: var(--error);
}

.balance-card .status.owed {
  color: var(--success);
}

.balance-card .status.settled {
  color: var(--text);
  opacity: 0.7;
}

.settlements {
  margin-top: 16px;
}

.settlement-item {
  background: var(--bg);
  border-left: 4px solid var(--accent);
  padding: 8px 12px;
  margin-bottom: 8px;
  font-size: 0.95rem;
}

.settlement-item strong {
  color: var(--accent);
}

@media (max-width: 400px) {
  .card {
    padding: 16px;
  }
  h1 {
    font-size: 1.4rem;
  }
  .totals-grid, .balances-grid {
    grid-template-columns: 1fr;
  }
}

(function() {
  'use strict';

  const FRIENDS = ['Alice', 'Bob', 'Charlie'];
  let expenses = [];

  const form = document.getElementById('expense-form');
  const payerSelect = document.getElementById('payer');
  const amountInput = document.getElementById('amount');
  const descriptionInput = document.getElementById('description');
  const errorDiv = document.getElementById('error-message');
  const expenseList = document.getElementById('expense-list');
  const totalsDiv = document.getElementById('totals');
  const balancesDiv = document.getElementById('balances');
  const settlementsDiv = document.getElementById('settlements');

  function formatCurrency(value) {
    return '$' + Math.abs(value).toFixed(2);
  }

  function renderExpenses() {
    expenseList.innerHTML = '';
    expenses.forEach(function(exp, index) {
      const li = document.createElement('li');
      li.className = 'expense-item';
      const info = document.createElement('span');
      info.className = 'expense-info';
      info.textContent = exp.payer + ' paid ' + formatCurrency(exp.amount) + (exp.description ? ' for ' + exp.description : '');
      const amountSpan = document.createElement('span');
      amountSpan.className = 'expense-amount';
      amountSpan.textContent = formatCurrency(exp.amount);
      const removeBtn = document.createElement('button');
      removeBtn.type = 'button';
      removeBtn.className = 'remove-btn';
      removeBtn.textContent = 'Remove';
      removeBtn.setAttribute('aria-label', 'Remove expense: ' + exp.payer + ' paid ' + formatCurrency(exp.amount));
      removeBtn.addEventListener('click', function() {
        expenses.splice(index, 1);
        renderAll();
      });
      li.appendChild(info);
      li.appendChild(amountSpan);
      li.appendChild(removeBtn);
      expenseList.appendChild(li);
    });
  }

  function renderTotals() {
    const totals = {};
    FRIENDS.forEach(function(f) { totals[f] = 0; });
    expenses.forEach(function(exp) {
      totals[exp.payer] += exp.amount;
    });
    totalsDiv.innerHTML = '';
    FRIENDS.forEach(function(f) {
      const card = document.createElement('div');
      card.className = 'total-card';
      card.innerHTML = '<div class="name">' + f + '</div><div class="amount">' + formatCurrency(totals[f]) + '</div>';
      totalsDiv.appendChild(card);
    });
  }

  function renderBalances() {
    const totalPaid = {};
    FRIENDS.forEach(function(f) { totalPaid[f] = 0; });
    let totalExpense = 0;
    expenses.forEach(function(exp) {
      totalPaid[exp.payer] += exp.amount;
      totalExpense += exp.amount;
    });
    const equalShare = totalExpense / FRIENDS.length;
    const balances = {};
    FRIENDS.forEach(function(f) {
      balances[f] = totalPaid[f] - equalShare;
    });

    balancesDiv.innerHTML = '';
    FRIENDS.forEach(function(f) {
      const bal = balances[f];
      const card = document.createElement('div');
      card.className = 'balance-card';
      let statusText, statusClass;
      if (Math.abs(bal) < 0.005) {
        statusText = 'Settled';
        statusClass = 'settled';
      } else if (bal > 0) {
        statusText = 'Is owed ' + formatCurrency(bal);
        statusClass = 'owed';
      } else {
        statusText = 'Owes ' + formatCurrency(bal);
        statusClass = 'owes';
      }
      card.innerHTML = '<div class="name">' + f + '</div><div class="status ' + statusClass + '">' + statusText + '</div>';
      balancesDiv.appendChild(card);
    });

    renderSettlements(balances);
  }

  function renderSettlements(balances) {
    settlementsDiv.innerHTML = '';
    const debtors = [];
    const creditors = [];
    FRIENDS.forEach(function(f) {
      const bal = balances[f];
      if (bal < -0.005) debtors.push({ name: f, amount: -bal });
      else if (bal > 0.005) creditors.push({ name: f, amount: bal });
    });

    debtors.sort(function(a, b) { return b.amount - a.amount; });
    creditors.sort(function(a, b) { return b.amount - a.amount; });

    const transactions = [];
    let i = 0, j = 0;
    while (i < debtors.length && j < creditors.length) {
      const debtor = debtors[i];
      const creditor = creditors[j];
      const amount = Math.min(debtor.amount, creditor.amount);
      if (amount > 0.005) {
        transactions.push({ from: debtor.name, to: creditor.name, amount: amount });
      }
      debtor.amount -= amount;
      creditor.amount -= amount;
      if (debtor.amount < 0.005) i++;
      if (creditor.amount < 0.005) j++;
    }

    if (transactions.length === 0) {
      settlementsDiv.innerHTML = '<p>All settled up!</p>';
      return;
    }

    transactions.forEach(function(t) {
      const div = document.createElement('div');
      div.className = 'settlement-item';
      div.innerHTML = '<strong>' + t.from + '</strong> pays <strong>' + t.to + '</strong> ' + formatCurrency(t.amount);
      settlementsDiv.appendChild(div);
    });
  }

  function renderAll() {
    renderExpenses();
    renderTotals();
    renderBalances();
  }

  form.addEventListener('submit', function(e) {
    e.preventDefault();
    errorDiv.textContent = '';

    const payer = payerSelect.value;
    const amount = parseFloat(amountInput.value);
    const description = descriptionInput.value.trim();

    if (!payer) {
      errorDiv.textContent = 'Please select who paid.';
      payerSelect.focus();
      return;
    }
    if (isNaN(amount) || amount <= 0) {
      errorDiv.textContent = 'Please enter a valid positive amount.';
      amountInput.focus();
      return;
    }
    if (!/^\d+(\.\d{1,2})?$/.test(amountInput.value.trim())) {
      errorDiv.textContent = 'Amount must have at most 2 decimal places.';
      amountInput.focus();
      return;
    }

    expenses.push({ payer: payer, amount: Math.round(amount * 100) / 100, description: description });
    form.reset();
    payerSelect.focus();
    renderAll();
  });

  renderAll();
})();
